sql_attempts.query:
SELECT COUNT(DISTINCT d.driverId) as driver_count
FROM drivers d
WHERE d.driverId IN (
    SELECT driverId FROM pitStops GROUP BY driverId HAVING COUNT(*) > 8
)
OR d.driverId IN (
    SELECT driverId FROM results GROUP BY driverId HAVING COUNT(*) > 5
);

SELECT COUNT(DISTINCT driverId) as pitstop_drivers
FROM (
    SELECT driverId FROM pitStops GROUP BY driverId HAVING COUNT(*) > 8
);

